import com.comsol.model.*;import com.comsol.model.util.*;
public class ProbeDeformation {public static void main(String[] a){try{ModelUtil.initStandalone(false);Model m=ModelUtil.create("m");m.component().create("c",true);m.component("c").geom().create("g",2);m.component("c").geom("g").create("r","Rectangle");m.component("c").geom("g").run();for(String t:new String[]{"PrescribedDeformation","PrescribedMeshDisplacement","PrescribedMeshVelocity"})try{m.component("c").common().create(t,t);InspectFeatures.dump(m.component("c").common(t),t);}catch(Exception e){System.out.println(t+" unavailable "+e.getMessage());}m.component("c").cpl().create("ext","GeneralExtrusion");InspectFeatures.dump(m.component("c").cpl("ext"),"Extrusion");System.exit(0);}catch(Throwable e){e.printStackTrace();System.exit(1);}}}
